# -*- coding: utf-8 --

from taf.rfrl.cbts.devices.vdu.base.vdu_ope_base import vDUOPE
from taf.rfrl.cbts.devices.vdu.base.vdu_cm_base import vDUCM
from taf.rfrl.cbts.devices.vdu.base.vdu_fm_base import vDUFM
from robot.libraries.BuiltIn import BuiltIn
from robot.api import logger

vdu_ope_base = vDUOPE()
vdu_cm_base = vDUCM()
vdu_fm_base = vDUFM()
builtin_obj = BuiltIn()

__all__ = [
    "no_unexpected_alarms_in_active_alarms"
]

LOG_HEAD = LOG_END = '*' * 8


def no_unexpected_alarms_in_active_alarms(user_unexpected_alarms=None, conn_alias='default'):
    """
    Checking no unexpected alarms in active alarms list. The unexpected alarms consists of default and user given alarms.

    :param str|list user_unexpected_alarms: user defined unexpected alarms, it can be a list, or a string,
                                           e.g, ['10', '34'], '10, 34', '10; 34', '10|34'. Default is empty.
    :param str conn_alias: rest api connection alias, default value is 'default'.
    :return boolean: True or False
    """
    check_unexpected_active_alarms = vdu_fm_base.get_needed_unexpected_active_alarms(user_unexpected_alarms)
    logger.info('{} Unexpected alarms are {} {}'.format(LOG_HEAD, check_unexpected_active_alarms, LOG_END))
    curr_fault_id_list = vdu_fm_base.get_fault_id_list_from_active_alarms(conn_alias=conn_alias)
    curr_unexpected_alarms = set(check_unexpected_active_alarms) & set(curr_fault_id_list)
    if curr_unexpected_alarms:
        logger.warn('{} Unexpected alarms {} appears {}'.format(LOG_HEAD, curr_unexpected_alarms, LOG_END))
        return False
    logger.info('No unexpected alarms')
    return True
